from 写入第二遍 import add
add('23_002',2.5,'16:9，低位正面远景，武士深色轮廓位于画面中央，米灰尘雾遮到身体下半；固定机位，焦点留在轮廓边缘。','尘中的武士先把一侧粗壮手臂压回石面，再由另一侧共同撑住；宽大胸肩从下沉状态抬起，躯干摇晃一下就稳住，四周碎石随受力轻轻滚开。尘雾从他肩外分开，巨大轮廓重新压在雾层上方，头缓慢对准画外青的方向。','米灰近地尘雾从浓到薄分层，后方铅蓝云天与较亮云层纹理始终高于尘层；石地仅在下方露出窄带。','上方云天冷白漫射，逆着较亮尘雾看去，武士轮廓较暗。','粗重撑地闷响、碎石缓滚，尘中低厚呼吸重新稳定。',phase='process',node={'武士.阶段':'重新撑起身体准备攻击'},meaning='再次撑起而非重伤不起，原作雾中巨大轮廓完整保留。')
add('24_001',2,'16:9，从武士粗壮肩背后低仰的头部近景，肩背横贯画面下方，中央头部立在云天前；固定机位，头肩轮廓与中缝可见。','武士肩背下压蓄住力量，头部随之缓慢挺起；两侧轮廓出现短而不规则的震颤，中央中缝逐渐绷紧，肩背的抖动由大变细，最后压成一瞬静止。','肩背上方只露铅蓝云天，云层明暗层次柔和；震颤线贴着主体轮廓。','上方云天冷白漫射，主体上缘较亮，中缝与肩背下侧压暗。','低沉蓄气与肌理绷紧的细响由散转集中，石地砂粒轻颤。',phase='preparation',node={'武士.阶段':'头肩震颤蓄势'},meaning='原作头肩后侧与震颤蓄势节点保留，不新增能量球、光源或器官变化。')
add('24_002',4,'16:9，青居左的头肩近景，视线落向画面右侧画外武士，右边留出一条云天空隙；固定机位。','青刚形成的把握感停住，头向一侧偏，眼睛先睁大、嘴巴松开；她看着武士的蓄势轮廓，眉毛慢慢往中间收，嘴角从疑惑的弯形拉直。说完后半句，她的肩先抬紧，双手在画外收近身体，眼睛不再离开对手。','铅蓝云天与低处稀薄米灰尘雾形成冷淡背景，右侧空隙保持可见。','上方云天冷白柔光，空地敞口返弱中性光。','青一口变浅的吸气，低沉蓄气声从对手方向继续逼紧。',ja=['…は？','この動き、見たことがある気がする。'],tone='前句疑惑短促，后句边辨认边变警觉，句尾不再轻松。',kind='mixed',phase='reaction',node={'青.阶段':'认出蓄势动作、准备闪避'},card={'opening':'青以为能掌握对手，突然发现熟悉而不妙的准备。','beats':['歪过头、松嘴生疑','眉收紧，嘴角拉直、肩先抬起'],'coupling':'认知推动闪避准备，不等喷流到身边才反应。','landing':'目光锁定武士，双手收近。'})
